/**
 * Abstract base for trading strategies.
 *
 * Every concrete strategy must implement `onBar(bar: Bar): Signal[]`.
 */

import { Bar } from '../domain/models/Bar';
import { Signal } from '../domain/interfaces/IStrategy';
import { IStrategy } from '../domain/interfaces/IStrategy';

export abstract class BaseStrategy implements IStrategy {
  public readonly name: string;

  constructor(name: string) {
    this.name = name;
  }

  /**
   * Called on each new bar from the data feed.
   * @param bar - OHLCV bar at or before current time.
   * @returns Array of signals generated by this strategy.
   */
  abstract onBar(bar: Bar): Signal[];

  /**
   * Optional initialization called before the backtest starts.
   */
  abstract init(): void;

  /**
   * Optional cleanup called after the backtest ends.
   */
  abstract onFinish(): void;
}
